import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill } from '../remotionShim';
// Library: none — native SVG pattern and CSS gradient for high performance 2D backgrounds



export type GridWallpaperProps = Record<string, any>;

const GridWallpaper: React.FC<GridWallpaperProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 15,
  colorTop = "#CDF2BF",
  colorBottom = "#E6C4ED",
  gridColor = "#ffffff",
  gridOpacity = 0.6,
  columns = 12,
  strokeWidthBase = 2,
  speedX = 0.5,
  speedY = 1.2,
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  // Parser safety for base background (though mostly obscured by gradient)
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Grid dimensional logic — anchoring cells to width for square aspect ratio
  const cellSize = width / columns;
  const scaledStrokeWidth = strokeWidthBase * s;

  // Infinite panning logic — modulo ensures float precision doesn't degrade over very long durations
  const offsetX = (frame * speedX) % cellSize;
  const offsetY = (frame * speedY) % cellSize;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {/* 1. Gradient Base Layer */}
      <AbsoluteFill
        style={{
          background: `linear-gradient(to bottom, ${colorTop}, ${colorBottom})`,
          transition: "none",
        }}
      />

      {/* 2. Seamless Panning Grid Layer */}
      <AbsoluteFill style={{ transition: "none" }}>
        <svg width="100%" height="100%" style={{ overflow: "visible" }}>
          <defs>
            <pattern
              id="seamless-animating-grid"
              width={cellSize}
              height={cellSize}
              patternUnits="userSpaceOnUse"
              patternTransform={`translate(${offsetX} ${offsetY})`}
            >
              {/* 
                Drawing only the top and left borders of each cell.
                When SVG perfectly tiles this pattern, it forms a complete grid 
                without any overlapping double-thick lines at cell boundaries.
              */}
              <path
                d={`M ${cellSize} 0 L 0 0 0 ${cellSize}`}
                fill="none"
                stroke={gridColor}
                strokeWidth={scaledStrokeWidth}
                opacity={gridOpacity}
                style={{ transition: "none" }}
              />
            </pattern>
          </defs>
          <rect 
            width="100%" 
            height="100%" 
            fill="url(#seamless-animating-grid)" 
            style={{ transition: "none" }} 
          />
        </svg>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default GridWallpaper;